// Annual savings line under yearly prices
document.querySelectorAll('.billed[data-m]').forEach(el => {
  const amt = el.previousElementSibling.querySelector('.amt');
  const s = document.createElement('div');
  s.className = 'save-line'; s.dataset.save = (amt.dataset.m - amt.dataset.y) * 12;
  el.after(s);
});
const _set = setPeriod;
setPeriod = function (y) {
  _set(y);
  document.querySelectorAll('.save-line').forEach(s => s.textContent = y ? 'You save $' + s.dataset.save + ' a year' : '');
};
// Plan recommender
const inv = document.getElementById('inv'), out = document.getElementById('invOut'), rec = document.getElementById('rec');
const plans = document.querySelectorAll('.plan');
function recommend() {
  const n = +inv.value; out.textContent = n;
  const i = n <= 5 ? 0 : 1;
  plans.forEach((p, k) => p.classList.toggle('glow', k === i));
  rec.textContent = i === 0 ? 'Starter covers you — free forever.' : 'Freelancer is your fit: unlimited invoices plus automatic reminders.';
}
inv.oninput = recommend; recommend(); setPeriod(true);
mBtn.onclick = () => setPeriod(false);

