file.content:
  section { padding: 84px 0 0; }
  h3.sec { font-family: var(--serif); font-size: 2.1rem; text-align: center; margin-bottom: 8px; letter-spacing: -.015em; }
  .sec-sub { text-align: center; color: var(--muted); margin-bottom: 32px; }

  .table-wrap { overflow-x: auto; border: 1.5px solid var(--line); border-radius: var(--radius); background: var(--card); }
  table { width: 100%; border-collapse: collapse; min-width: 580px; font-size: .95rem; }
  th, td { padding: 14px 20px; text-align: center; border-bottom: 1px solid var(--line); }
  th:first-child, td:first-child { text-align: left; }
  thead th { font-family: var(--mono); text-transform: uppercase; font-size: .78rem; letter-spacing: .06em; }
  th:nth-child(3), td:nth-child(3) { background: var(--tint); font-weight: 600; }
  th:nth-child(3) { color: var(--stamp); }
  tbody tr:last-child td { border-bottom: 0; }
  td:first-child { color: var(--muted); font-weight: 400; }
  .yes { color: var(--stamp); font-weight: 800; }
  .no { color: var(--muted); }

  .proof { display: grid; grid-template-columns: 1.3fr 1fr; gap: 24px; margin-top: 84px; align-items: stretch; }
  .quote { background: var(--ink); color: var(--paper); border-radius: var(--radius); padding: 36px; }
  @media (prefers-color-scheme: dark) { .quote { background: var(--card); border: 1.5px solid var(--line); color: var(--ink); } }
  .quote p { font-family: var(--serif); font-size: 1.5rem; line-height: 1.3; margin-bottom: 14px; }
  .quote small { font-family: var(--mono); font-size: .8rem; opacity: .85; }
  .guarantee { border: 1.5px solid var(--ink); border-radius: var(--radius); padding: 30px; display: flex; flex-direction: column; justify-content: center; gap: 10px; position: relative; }
  .guarantee .seal { font-family: var(--mono); font-size: .75rem; text-transform: uppercase; letter-spacing: .08em; color: var(--stamp); font-weight: 800; border: 2px solid var(--stamp); align-self: flex-start; padding: 4px 10px; border-radius: 6px; transform: rotate(-3deg); }
  .guarantee b { font-family: var(--serif); font-size: 1.35rem; }
  .guarantee span.t { color: var(--muted); font-size: .95rem; }
  .trust { margin-top: 48px; text-align: center; color: var(--muted); font-size: .85rem; font-family: var(--mono); text-transform: uppercase; letter-spacing: .06em; }
  .trust ul { list-style: none; padding: 0; display: flex; justify-content: center; flex-wrap: wrap; gap: 10px 36px; margin-top: 12px; font-family: var(--serif); text-transform: none; letter-spacing: 0; font-size: 1.25rem; font-weight: 700; color: var(--ink); opacity: .8; }

  .faq { max-width: 740px; margin: 0 auto; }
  details { border-bottom: 1.5px solid var(--line); padding: 18px 0; }
  summary { cursor: pointer; font-weight: 600; font-size: 1.05rem; list-style: none; display: flex; justify-content: space-between; gap: 16px; }
  summary::-webkit-details-marker { display: none; }
  summary::after { content: "+"; font-family: var(--mono); font-size: 1.4rem; line-height: 1; color: var(--stamp); }
  details[open] summary::after { content: "–"; }
  details p { color: var(--muted); margin-top: 10px; }

  .cta { text-align: center; padding: 90px 0; }
  .cta h3 { font-family: var(--serif); font-size: clamp(1.8rem, 4vw, 2.6rem); margin-bottom: 22px; letter-spacing: -.015em; }
  .cta .btn { display: inline-block; padding: 15px 36px; font-size: 1.05rem; }
  .cta p { color: var(--muted); margin-top: 14px; font-size: .9rem; }

  footer { border-top: 1.5px solid var(--ink); padding: 22px 0 32px; color: var(--muted); font-size: .85rem; }
  footer .wrap { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 8px; font-family: var(--mono); }

  @media (max-width: 900px) {
    .plans { grid-template-columns: 1fr; max-width: 460px; margin: 52px auto 28px; gap: 34px; }
    .plan.featured { order: -1; margin-top: 0; }
    .tag { min-height: 0; }
    .proof { grid-template-columns: 1fr; }
    nav .links a:not(:last-child) { display: none; }
  }
  @media (max-width: 480px) {
    .wrap { padding: 0 18px; }
    .meta { font-size: .7rem; }
    .stamp { right: -4px; }
  }
  @media (prefers-reduced-motion: reduce) { .btn { transition: none; } html { scroll-behavior: auto; } }
