const inv = $('#inv'), out = $('#invOut'), rec = $('#rec'), plans = $$('.plan');
function recommend() {
  const n = +inv.value; out.textContent = n;
  const i = n <= 5 ? 0 : 1;
  plans.forEach(p => p.classList.toggle('is-pick', +p.dataset.i === i));
  rec.textContent = i === 0
    ? 'Starter covers you. Free forever, and you can upgrade the day you outgrow it.'
    : n > 25
      ? 'Freelancer is your fit. At this volume, automatic reminders will earn their keep.'
      : 'Freelancer is your fit: unlimited invoices plus reminders that chase for you.';
}
inv.oninput = recommend;
recommend(); setPeriod(true);

input.new_string:
const inv = $('#inv'), cli = $('#cli'), team = $('#team'), rec = $('#rec'), plans = $$('.plan');
function recommend() {
  const n = +inv.value, c = +cli.value;
  $('#invOut').textContent = n; $('#cliOut').textContent = c;
  const i = team.checked ? 2 : (n > 5 || c > 3) ? 1 : 0;
  plans.forEach(p => p.classList.toggle('is-pick', +p.dataset.i === i));
  rec.textContent = [
    'Starter covers you: up to 5 invoices and 3 clients, free forever. Upgrade the day you outgrow it.',
    n > 5 && c > 3 ? 'Freelancer is your fit: you’re past Starter’s 5 invoices and 3 clients.'
      : n > 5 ? 'Freelancer is your fit: Starter stops at 5 invoices a month, and reminders will chase the rest for you.'
      : 'Freelancer is your fit: Starter stops at 3 active clients.',
    'Studio is your fit: collaborators get their own logins, and everything in Freelancer comes along.'
  ][i];
}
[inv, cli, team].forEach(el => el.oninput = recommend);
recommend(); setPeriod(true);

