input.new_string:
let cur = 0, isYearly = true;
const NAMES = ['Starter', 'Freelancer', 'Studio'];
const fmtDate = d => d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };
const money = n => '$' + n.toFixed(2);
window.trialEnd = d => fmtDate(addDays(d, 14));
function renderInvoice(now = new Date()) {
  const name = NAMES[cur], a = $$('.plan')[cur].querySelector('.amt'), paid = cur > 0;
  const mo = paid ? +a.dataset.m : 0, yr = paid ? +a.dataset.y : 0, price = isYearly ? yr * 12 : mo;
  const lines = paid
    ? [[name + ' plan · ' + (isYearly ? money(yr) + ' × 12 months' : '1 month'), money(price)], ['14-day free trial', '−' + money(price), true]]
    : [['Starter plan', money(0)]];
  $('#invLines').innerHTML = lines.map(l => '<div class="inv-line' + (l[2] ? ' neg' : '') + '"><span>' + l[0] + '</span><span>' + l[1] + '</span></div>').join('');
  $('#invDate').textContent = fmtDate(now);
  $('#invNote').textContent = paid
    ? 'Your trial ends ' + fmtDate(addDays(now, 14)) + '. Love it? Keep ' + name + ' for ' + money(price) + (isYearly ? ' a year' : ' a month') + '. If not, you drop to Starter at $0, with nothing to cancel.'
    : 'Free for as long as you like. We’ll never ask for a card.';
}
function setPeriod(yearly) {
  isYearly = yearly; renderInvoice();

